(()=>{'use strict';const nav=[...document.querySelectorAll('[data-section]')],sections=[...document.querySelectorAll('.explore-section')];if(!sections.length)return;const search=document.querySelector('#explore-search'),count=document.querySelector('#explore-count'),status=document.querySelector('#copy-status');let active='works';document.querySelector('.explore-tools').hidden=false;function filter(){const terms=search.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let shown=0,total=0;sections.forEach(s=>{s.hidden=s.id!==active;if(s.hidden)return;s.querySelectorAll('.explore-entry').forEach(e=>{total++;e.hidden=!terms.every(t=>e.dataset.search.includes(t));if(!e.hidden)shown++});const art=s.querySelector('.art-pair');if(art)art.hidden=terms.length>0});nav.forEach(a=>a.setAttribute('aria-current',String(a.dataset.section===active)));count.textContent=shown+' of '+total+' entries';document.querySelector('#explore-empty').hidden=shown!==0;}
function route(){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{id=''}const target=document.getElementById(id),section=target?.closest('.explore-section');active=section?.id||'works';search.value='';status.textContent='';filter();if(target)requestAnimationFrame(()=>(target===section?document.querySelector('.explore-tools'):target).scrollIntoView({block:'start'}));}
nav.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();active=a.dataset.section;search.value='';filter();if(location.hash==='#'+a.dataset.section)route();else location.hash=a.dataset.section}));addEventListener('hashchange',route);search.addEventListener('input',filter);document.querySelector('#clear-search').addEventListener('click',()=>{search.value='';filter();search.focus()});document.querySelectorAll('.copy-idea').forEach(b=>{b.hidden=false;b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';status.textContent='Copied: '+b.closest('article').querySelector('h3').textContent;setTimeout(()=>b.textContent='Copy for Post-it',2000)}catch{const range=document.createRange();range.selectNodeContents(b.closest('article'));getSelection().removeAllRanges();getSelection().addRange(range);status.textContent='Text selected. Use your browser’s Copy command.'}})});
const dialog=document.querySelector('#art-view');let opener;document.querySelectorAll('.art-open').forEach(a=>a.addEventListener('click',e=>{if(typeof dialog.showModal!=='function')return;e.preventDefault();opener=a;document.querySelector('#art-view-title').textContent=a.dataset.artTitle;const img=document.querySelector('#art-view-image');img.src=a.href;img.alt=a.querySelector('img').alt;dialog.showModal()}));document.querySelector('#close-art').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});route();})();
